FIELDS=['maxHp','armor','moveSpeed','physical','special','damage']
def baseline(raw,stage):
 total=sum(raw.values());n=lambda k:raw[k]/total*6;growth=1+.12*stage
 return dict(maxHp=math.floor((70+45*n('hp'))*growth+.5),armor=6*n('def')+3*n('spd'),moveSpeed=.92+.12*n('spe'),physical=.82+.2*n('atk'),special=.82+.2*n('spa'),damage=growth)
def stat_text(x):
 return f"HP {x['maxHp']} · armor {x['armor']:.1f} · speed ×{x['moveSpeed']:.2f} · physical ×{x['physical']:.2f} / special ×{x['special']:.2f} · growth damage ×{x['damage']:.2f}"
def apply_depth(ctx):
 P,pages,article,table,ref=ctx['P'],ctx['PAGES'],ctx['article'],ctx['table'],ctx['ref']
 old=ctx['DATE'],ctx['VERSION'];ctx['DATE'],ctx['VERSION']='October 28, 2026','v0.8.62'
 src=[(D['source_client'],'pokebonk.com — original v0.8.62 client','Checked October 28, 2026. SINGLE_SOURCE: source inspection and derived calculations, not gameplay, measured DPS or a completed run.'),(D['source_news'],'pokebonk.com — original v0.8.62 configuration','Season 2 rules, regions and medal schedules; checked October 28. The game host and future versions may differ.')]
 scope='<p class="note">Applies to the original v0.8.62; our embedded Play edition is v0.8.27. Calculations are source-derived, not gameplay measurements.</p>'
 # Add source-derived baselines and runtime templates to the existing combined database.
 page=pages[P+'pokemon/'];s=page['html']
 for x in D['league']:
  rows=[]
  for f in x['forms']:
   b=baseline(f['raw'],f['stage']);rows.append([e(f['name']),e(f['at']),str(b['maxHp']),f"{b['armor']:.1f}",f"×{b['moveSpeed']:.2f}",f"×{b['physical']:.2f} / ×{b['special']:.2f}",f"×{b['damage']:.2f}"])
  if len(x['forms'])==1:
   for stage,level in [(1,24),(2,44)]:
    f=x['forms'][0];b=baseline(f['raw'],stage);rows.append([e(f['name']),f'Level {level} growth (same form)',str(b['maxHp']),f"{b['armor']:.1f}",f"×{b['moveSpeed']:.2f}",f"×{b['physical']:.2f} / ×{b['special']:.2f}",f"×{b['damage']:.2f}"])
  u=x['ultimate'];ult=''.join(f'<li><strong>{e(name)}</strong> — {e(u["descs"][i])}</li>'for i,name in enumerate(u['names']))
  moves=table(['Move','Runtime class / shape','Base template hit / cooldown','Status source'],[[e(m['name']),e(m['runtime']['cls']+' / '+m['runtime']['arch']),f"{m['runtime']['dmg']:.2f} / {m['runtime']['cd']:.2f}s",e(m['runtime']['status']or 'None')]for m in x['kit']])
  more='<div class="partner-numbers"><h3>Form baselines</h3><p>Before passive, Lab, items and vitamins. Armor is a stat, not a damage-reduction percentage. Growth is included only at the listed stage.</p>'+table(['Form','Milestone','HP','Armor','Move speed','Physical / special','Growth damage'],rows)+'<h3>Move templates</h3><p>Base template values, not damage per second. Hits, projectiles, range, upgrades, enemy armor and timing change the result.</p>'+moves+'<h3>Ultimate stages</h3><ol>'+ult+'</ol><p><a href="/pokebonk/ultimates/#ult-'+str(x['id'])+'">Read the Ultimate reference</a></p></div>'
  pattern=r'(<details class="partner-card" id="pokemon-'+str(x['id'])+r'".*?)(</details>)'
  s,n=re.subn(pattern,lambda m:m[1]+more+m[2],s,count=1,flags=re.S);assert n==1
 controls='<section class="collection-controls" aria-label="Personal unlock checklist"><h3>Your unlock checklist</h3><p>Mark partners you have unlocked yourself. This is your manual checklist, not your live game account.</p><label>Show <select id="collection-filter"><option value="all">All partners</option><option value="owned">Marked unlocked</option><option value="missing">Not marked unlocked</option></select></label><button type="button" id="save-collection">Save checklist on this browser</button><button type="button" id="clear-collection">Clear checklist</button><p id="collection-status" role="status">Nothing is saved until you press Save checklist.</p></section>'
 s=s.replace('<div id="partner-cards"',controls+'<div id="partner-cards"',1)
 for x in D['league']:
  needle=f'<label class="compare-pick"><input type="checkbox" data-compare="{x["id"]}">'
  s=s.replace(needle,f'<label class="collection-pick"><input type="checkbox" data-collected="{x["id"]}"> Mark {e(x["name"])} unlocked in my checklist</label>'+needle,1)
 page['html']=s.replace('Evolution (.55)','Evolution (.62)')
 # The existing tools' source statement now reflects fields actually rechecked this batch.
 for slug in ['pokemon','build-planner','lab']:
  s=pages[P+slug+'/']['html'];s=s.replace('Fusion recipes and evolution levels retain the October 26 v0.8.55 reference.','All 106 fusion recipes and the Season 2 League evolution rules were rechecked against the same v0.8.62 client.').replace('recipes/evolution retain dated v0.8.55 source fields.','Fusion recipes and League evolution rules also rechecked against this client.').replace('Recipe and evolution fields retain this snapshot, not a full .62 recheck.','Historical reference only; displayed tools use the .62 recheck.')
  pages[P+slug+'/']['html']=s
 # Planner diagnosis and explicit, optional local saves are adjacent to the actual result.
 page=pages[P+'build-planner/'];s=page['html'];s=s.replace('<div id="plan-pairs"','<section id="plan-diagnosis" aria-labelledby="diagnosis-title"><h3 id="diagnosis-title">Check this combination</h3><ul id="diagnosis-list"></ul><p>Rules identify relevant bonuses and conditions. They do not simulate damage, item drops or a winning run.</p></section><div id="plan-pairs"',1)
 save='<section class="plan-saves" aria-labelledby="saves-title"><h3 id="saves-title">Save a draft on this device</h3><label>Draft name <input id="draft-name" maxlength="60" placeholder="Forest practice"></label><button id="save-draft" type="button">Save current draft</button><label>Saved drafts <select id="saved-drafts"><option value="">Choose a draft</option></select></label><button id="load-draft" type="button">Load draft</button><button id="delete-draft" type="button">Delete selected draft</button><p id="draft-status" role="status">Optional local storage on this browser. Sharing uses the existing URL. This is not a game save.</p></section>'
 s=s.replace('</form>',save+'</form>',1);page['html']=s
 # Complete practical starter routes using known kit choices, without claiming optimal builds.
 route_rows=[['Bulbasaur: sustain/control','Razor Leaf + Solar Beam → Flower Beam','Keep Vine Whip while building the pair; Sleep Powder is the control alternative.','Grass-related bonuses have a matching kit; check Synthesis healing and attack timing.','1','razor-leaf','solar-beam'],['Charmander: Fire area','Fire Spin + Flamethrower → Fiery Whirlwind','Keep Ember if a target card does not appear. Do not abandon a functioning attack just to chase a pair.','Charcoal matches Fire attacks. Low-HP passive damage remains conditional; do not assume it is always active.','4','fire-spin','flamethrower'],['Squirtle: Water control','Rapid Spin + Hydro Pump → Hydro Spiral','Keep Water Gun or Bubble until the pair is ready.','Mystic Water matches Water attacks. Defensive effects and low-HP damage have different activation conditions.','7','rapid-spin','hydro-pump']]
 # Validate the proposed pairs against the actual current recipes before writing them.
 for row in route_rows:
  x=next(x for x in D['league']if x['id']==int(row[4]));assert {row[5],row[6]} <= {m['key']for m in x['kit']};assert any(set(f.get('moves')or [])=={row[5],row[6]}and f.get('member')==x['id']for f in D['fusions'])
 routes=table(['Route','Mid-run pair','Before the pair appears','What to check next'],[[e(a),e(b),e(c),e(d)+f'<p><a href="/pokebonk/build-planner/?partner={ident}&amp;m0={m0}&amp;m1={m1}">Open this draft</a></p>']for a,b,c,d,ident,m0,m1 in route_rows])
 extra=ctx['section']('route-checkpoints','Choose a route, then keep a fallback','<p>These are source-based practice drafts, not measured best builds. Start with a working attack, grow the two named ingredients, and check Bill’s Machine eligibility before treating the fusion as available.</p>'+routes+'<ol><li>Before the run: select the partner, check three or four move slots, and budget any missing Lab unlock.</li><li>During upgrades: distinguish a new move, an upgrade to an existing move and a vitamin. Leave room for your pair instead of filling every slot without a plan.</li><li>At Bill’s Machine: the required moves must meet the game’s current level and eligibility rules; a valid planning pair does not bypass them.</li><li>If the run fails: record the zone, missing ingredient and damage source. Change one decision before your next attempt.</li></ol>'+ref(1))
 page=pages[P+'builds/'];page['html']=page['html'].replace('<section class="sources"',extra+'<section class="sources"',1)
