 for x in D['league']:
  u=x['ultimate'];cards.append(f'<details class="ultimate-entry" id="ult-{x["id"]}" data-ult-search="{e((x["name"]+" "+" ".join(x["aliases"])+" "+u["type"]+" "+" ".join(u["names"])).lower())}"><summary>{e(x["name"])} · {e(u["type"])} / {e(u["cls"])}</summary><ol>'+''.join(f'<li><strong>{e(name)}</strong><p>{e(u["descs"][i])}</p></li>'for i,name in enumerate(u['names']))+f'</ol><a href="/pokebonk/pokemon/#pokemon-{x["id"]}">Check forms, kit and unlock conditions</a> · <a href="/pokebonk/build-planner/?partner={x["id"]}">Plan this partner</a></details>')
 article('ultimates','PokeBonk Ultimates: All 79 Partners & Evolution Stages','Find your partner’s Ultimate and its stages','Search all 79 PokeBonk partner Ultimates, compare evolution stages and understand charge, controls and effect limits using the checked game client.','Choose your partner below to read its Ultimate stages alongside the kit and evolution reference. The v0.8.62 client defines a signature entry for all 79 current League partners.'+ref(1),[('reference','Search the Ultimate reference',scope+'<label>Partner, Chinese name, Ultimate or type <input id="ultimate-search" type="search" placeholder="Mewtwo, 妙蛙种子 or grass"></label><p id="ultimate-count" role="status">79 partners</p><div class="ultimate-grid">'+''.join(cards)+'</div>'),('using','Before you rely on an Ultimate','<p>The default desktop action is R; Y toggles automatic casting. Check Settings if you remapped the controls, and wait for the ready indicator. Auto casting also checks for a nearby enemy, rather than promising an immediate cast anywhere.</p><p>While no Ultimate is active, the checked client replenishes charge over time. Kills and received damage also add charge; ability, item and Lab effects can change its rate. Deliberately taking damage is not a safe charging strategy. The client does not simply charge the meter from every point of outgoing damage.</p><p>Names and effects are ordered as the client lists them. Multi-stage entries change with form progression; they are not three independent moves occupying your move slots. A single named entry is not evidence that its strength is identical at every player level.</p>'+ref(1)),('decide','Match the effect to the problem','<p>Read effects for the situation you need: an area clear, control, movement or recovery. Do not infer sustained DPS from a dramatic description. Return to the partner’s passive and move templates before changing the rest of the build.</p><p>Ultimate charging, enemy overlap and player level are not simulated by our planner. Record what actually happens in your run before treating a practice draft as a recommendation.</p>'+ref(2))],src,[('pokemon/','Compare the partner’s complete kit'),('build-planner/','Draft a compatible build')],script='depth.js')
 # PokeBonk's transformed chart is intentionally separate from main-series values.
 types=D['typeChart']['types'];chart=D['typeChart']['chart']
 def effective(i,j):
  v=chart[i][j];return 1.35 if v>=2 else .5 if v==0 else .8 if v<=.5 else 1
 charttable=table(['Attack ↓ / defense →']+[t.title()for t in types],[[t.title()]+[f'{effective(i,j):g}×'for j in range(len(types))]for i,t in enumerate(types)])
 opts=''.join(f'<option value="{t}">{t.title()}</option>'for t in types)
 calc='<div class="tool"><label>Attack type <select id="attack-type">'+opts+'</select></label><label>Defender type 1 <select id="defense-one">'+opts+'</select></label><label>Defender type 2 <select id="defense-two"><option value="">None</option>'+opts+'</select></label><label>Matching-type bonus <select id="stab"><option value="1">No matching type</option><option value="1.25">Matching type</option><option value="1.5625">Adaptability matching type</option></select></label><p id="type-result" role="status"></p></div>'
 article('type-chart','PokeBonk Type Chart & Dual-Type Damage Calculator','Check PokeBonk’s own type multipliers','Calculate PokeBonk attack types against single or dual types, separate matching-type bonuses, and read the checked chart without main-series assumptions.','PokeBonk transforms the familiar type chart: favorable matchups use 1.35×, resisted ones 0.8× and classic immunities 0.5×. Dual-type results are multiplied and clamped to 0.4–1.8× before the separate matching-type bonus.'+ref(1),[('calculator','Calculate a type matchup',scope+calc+ref(1)),('chart','Read all 18 attack types',charttable+'<p>This matrix shows a single defender type before the matching-type bonus. Use the calculator for two distinct defender types.</p>'+ref(1)),('layers','Keep three different questions separate',table(['Question','What to read','Why it matters'],[['What element hits?','Move type versus defender types','Use this chart.'],['Which offense stat applies?','Runtime physical or special class','A Water move is not automatically special.'],['What else changes damage?','Matching type, passive, items, reactions and enemy conditions','The chart is one layer, not a DPS result.']])+'<p>Matching type uses 1.25×, or 1.5625× with Adaptability. These are separate from the dual-type clamp. A listed reaction still needs its status and hit conditions; a favorable chart entry does not create a status by itself.</p>'+ref(1)+ref(2))],src,[('build-planner/','Check the classes in your draft'),('luck-status-chance/','Separate status chance from Luck')],script='depth.js')
 # Survival and Time Attack answer separate run objectives, not synonyms of Classic clear.
 timeline=table(['Elapsed time','Viridian Forest checkpoint','Your decision'],[['05:00 / 10:00','Guardian checkpoints','Restore control and read the post-boss pact before choosing.'],['15:00','Mew milestone','A milestone encounter is not the same as an unlocked League capture.'],['30:00','Moltres milestone','Check survival/control and the curse costs already accepted.'],['45:00','Mewtwo milestone; Endless Night begins','Expect continued pressure rather than a Classic victory screen.']])
 article('survival','PokeBonk Survival: Milestones, Pacts & Endless Night','Plan a Survival run by its next milestone','Understand PokeBonk Survival milestones, pacts, Endless Night and scoring boundaries, with a dated Forest timeline and a checklist for each attempt.','Survival is an endless run, not the three-zone Classic clear. Plan around five-minute boss checkpoints and your next survival target; Viridian Forest’s listed special milestones are Mew at 15, Moltres at 30 and Mewtwo at 45 minutes.'+ref(1),[('timeline','Use the Forest milestone timeline',scope+timeline+'<p>This is the checked Forest reference. Do not copy its named bosses to every region or mistake elapsed times for a promise that a boss dies immediately.</p>'+ref(1)),('pacts','Choose a pact by its cost as well as its power','<p>After a milestone boss, read both parts of the offered pact: the benefit and its curse. A damage increase is not automatically useful if its cost removes the defense keeping the run alive. Keep a note of curses already accepted so later choices are assessed against the whole run.</p><p>Before committing, ask whether your draft can still move, recover and control incoming enemies. Our planner records a draft; it does not calculate a pact-adjusted survival time.</p>'+ref(1)),('night','Prepare for continued pressure','<p>The configuration places Endless Night at 2,700 seconds. Staying alive beyond that point is continued progression, not a hidden Classic completion. Avoid treating a movement-only draft as an indefinite escape strategy.</p><p>Choose the next achievable checkpoint, keep attacks that actually reach the horde, and recheck recovery after each major upgrade. These are editorial planning steps, not a tested record build.</p>'+ref(2)),('records','Separate score, time and unlock progress','<p>The client tracks several outcomes. An endless score can include kills, time, damage, bosses and legendary encounters, while the Survival board description ranks elapsed time first and uses KOs to break ties. Record mode and region alongside the number you compare.</p><p>A boss encounter does not bypass the partner’s League challenge or capture requirements. Use the partner database before spending a long attempt on an unlock it cannot satisfy.</p>'+ref(1)),('checklist','Before the next attempt','<ol><li>Confirm Survival and the intended region in preparation.</li><li>Check your partner’s actual attacks, control options and Lab budget.</li><li>Set a next-checkpoint target rather than assuming an endless win condition.</li><li>After the run, record elapsed time, accepted curses and the immediate cause of failure.</li></ol>')],src,[('how-to-win/','Use the Classic clear guide instead'),('mewtwo/','Check Mewtwo’s distinct unlock requirements'),('build-planner/','Plan a milestone-focused kit')])
 def clock(n):return f'{n//60}:{n%60:02d}'
 medals=D['medals'];medalrows=[];region_names={x['id']:x['name']for x in D['maps']}
