 home=home.replace('<p id="guide-search-status" role="status"></p>','<p id="guide-search-status" role="status"></p><ul id="guide-results">'+''.join(rows)+'</ul>')
 home=home.replace('</head>','<script src="/assets/pokebonk/depth.js" defer></script></head>');pages[P]['html']=home
 for slug,newslug,label in [('how-to-win','survival','Plan a Survival milestone instead'),('maps','time-attack','Check medal times by region'),('pokemon','ultimates','Search all Ultimate stages'),('build-planner','type-chart','Check a type matchup')]:
  p=pages[P+slug+'/'];p['html']=p['html'].replace('<section class="related">',f'<p><a href="{P+newslug}/">{label} →</a></p><section class="related">',1)
 # State current Season 2 branch scope without rewriting historical tables into current facts.
 p=pages[P+'evolution/'];note=ctx['section']('season-two-branches','Use the current Season 2 League branch list','<p>The original v0.8.62 League entry offers Eevee’s three Kanto branches: Vaporeon, Jolteon and Flareon at level 36. Older all-generation data can also contain later-generation species; their presence in a raw file does not make them selectable in the current season.</p><p>For the current filtered forms and levels of every League partner, use the <a href="/pokebonk/pokemon/">rechecked partner database</a>. The original examples below retain their stated historical version.</p>'+ctx['ext'](D['source_news'],'pokebonk.com — current Season 2 League configuration'))
