 lookup='<div class="reference-filter" data-reference><label>Find a partner or form <input type="search" placeholder="Eevee or Golbat"></label><p data-result role="status">79 rows</p>'+table(['Partner','Route / run level','Method'],evo_rows)+'</div>'
 article('evolution',oldpage['title'],h1,oldpage['desc'],'Use the League’s run-evolution thresholds rather than main-series levels or stone requirements. The current Season 2 Eevee entry offers Vaporeon, Jolteon and Flareon at level 36; completing a run evolution is separate from permanently unlocking a League partner.'+ref(1)+ref(2),[('roster','Search all 79 current Season 2 routes',scope+lookup),('check','Read your next evolution before spending upgrades','<ol><li>Check the starting League partner, not a different form’s profile.</li><li>Read the next-evolution indicator during the run.</li><li>Earn run experience until its displayed threshold. A branch opens a choice rather than requiring a random reset.</li><li>After evolving, inspect the new form and its Ultimate stage.</li></ol>'+ref(1)),('eevee','Choose among the current Eevee branches','<p>The current League entry lists Vaporeon, Jolteon and Flareon at level 36. Raw all-generation files can contain later forms that are not active Season 2 choices. Do not treat an unfiltered species file as the playable branch list.</p>'+ref(2)),('method','How the thresholds and baselines are derived','<p>For a first evolution that still has a later form, the client adds 8 to the next form’s raw level and clamps to 16–30. For a final evolution, it rounds 22 + 0.6 × the raw level and clamps to 36–50. League overrides take priority. A later evolution has a minimum three-level gap.</p><p>The lookup filters species through the current Season 2 set before deriving routes. Same-form growth at levels 24 and 44 can increase HP and damage for partners without a remaining evolution; it does not create another species. Form baselines and growth are different from a completed gameplay test.</p>'+ref(1)),('progress','Keep run growth and League progress separate','<p>Evolution changes the partner in the current run. A League unlock uses its challenge and capture process. If the evolution indicator does not match this dated snapshot, record the host and version before applying another guide’s rule.</p>')],src,[('pokemon/','Compare current forms and base stats'),('ultimates/','Read Ultimate stages'),('how-to-catch-pokemon/','Unlock a permanent partner')],script='reference.js')
 p=pages[P+'privacy/'];p['html']=p['html'].replace('<h2>Questions or corrections</h2>','<h2>Optional local build drafts</h2><p>If you press Save current draft, this browser stores the draft name and planning URL in localStorage under pb-build-drafts-v1. Saved drafts stay on this browser and are not sent to the game or a new service. Load restores the URL; Delete selected draft removes one saved entry. Storage can be unavailable or cleared by the browser. A planning draft is not a game save and does not recover your account. The optional manual unlock checklist stores only selected partner IDs under pb-partner-checklist-v1 when you press Save checklist; Clear checklist removes it. It does not read game progress. Share links work without saving locally.</p><h2>Questions or corrections</h2>',1)
